import React from 'react';

const Footer = () => {
  return (
    <footer style={{
      backgroundColor: '#ffffff',
      borderTop: '1px solid #e2e8f0',
      padding: '24px',
      textAlign: 'center',
      marginTop: 'auto',
      fontSize: '13px',
      color: '#64748b',
    }}>
      <p>AuraStore MERN E-Commerce Architecture &bull; Document Version 1.0.0 (Production)</p>
    </footer>
  );
};

export default Footer;
